// Verbatim actual DCD wrapper/capture namespace and HTTP/auth functions are compiled.
// Only event delivery, original-handler forwarding and HTTP lower APIs are mocks.
#include "http_fixture.h"
#include <mutex>
#include "device/dcd.h"
#include "actual_observer.inc"
#include "actual_handlers.inc"
static void contains(const std::string&s,const std::string&part){check(s.find(part)!=std::string::npos,part.c_str());}
static void absent(const std::string&s,const std::string&part){check(s.find(part)==std::string::npos,part.c_str());}
static void reset(){if(!allocated.empty())throw std::runtime_error("WString survived prior integration group");usb_observer::resetForTest();evilduck_mock_dcd_reset();bootCalls=0;execution::busy=execution::tryBusy=false;execution::depth=0;nowMs=7000;allocationLimit=1000000;largestRequest=0;}
static dcd_event_t event(uint8_t kind){dcd_event_t e{};e.rhport=0;e.event_id=kind;return e;}
static dcd_event_t setup(uint8_t type=0x80,uint8_t request=6,uint16_t value=0x0100,uint16_t index=0,uint16_t length=18){auto e=event(DCD_EVENT_SETUP_RECEIVED);uint8_t b[]={type,request,uint8_t(value),uint8_t(value>>8),uint8_t(index),uint8_t(index>>8),uint8_t(length),uint8_t(length>>8)};std::memcpy(&e.setup_received,b,sizeof(b));return e;}
static void deliver(dcd_event_t&e,bool isr=true){const auto n=evilduck_mock_dcd_calls();__wrap_dcd_event_handler(&e,isr);check(evilduck_mock_dcd_calls()==n+1,"wrapper must forward exactly once");check(evilduck_mock_dcd_last()==&e&&evilduck_mock_dcd_last_isr()==isr,"original event pointer/context changed");}
static void start(){auto e=event(DCD_EVENT_BUS_RESET);e.bus_reset.speed=TUSB_SPEED_FULL;deliver(e);}
static void read(AsyncWebServerRequest&r){r.headers["X-Duck-Password"]="synthetic-password-only";handleUsbObservations(&r);check(r.status==200&&r.type=="application/json","authenticated capture export failed");check(r.responseHeaders["Cache-Control"]=="no-store","capture cache boundary lost");check(execution::depth==0,"export leaked execution guard");absent(r.body,"synthetic-password-only");}
static void report(const char*name,unsigned before){++groups;std::cout<<"{\"id\":\""<<name<<"\",\"status\":\"PASS\",\"assertions\":"<<checks-before<<"}"<<std::endl;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("output directory required");const std::string out=argv[1];unsigned before;
 reset();before=checks;{start();auto e=setup();deliver(e,false);usb_observer::service(1000,true);usb_observer::service(6000,true);const auto old=usb_observer::snapshot();AsyncWebServerRequest r;read(r);const auto after=usb_observer::snapshot();check(old.count==1&&old.records[0].wValue==0x0100,"wrapper did not populate real capture");check(after.count==old.count&&after.generation==old.generation&&after.observed==old.observed,"read altered capture");contains(r.body,"\"state\":\"COMPLETE\"");contains(r.body,"\"windowElapsedMs\":5000");contains(r.body,"\"unsupported\":0,\"unsupportedReasons\":0");contains(r.body,"\"count\":1");contains(r.body,"\"wValue\":256");contains(r.body,"\"classification\":\"UNKNOWN\"");std::ofstream(out+"/integration-complete.json")<<r.body;}report("UI01",before);
 reset();before=checks;{start();auto e=setup();deliver(e);AsyncWebServerRequest r;r.headers["X-Duck-Password"]="wrong";r.params["pw"].data="synthetic-password-only";handleUsbObservations(&r);check(r.status==401&&bootCalls==0,"wrong header authorized integration capture");absent(r.body,"?pw=");check(usb_observer::snapshot().count==1,"auth failure changed captured bytes");AsyncWebServerRequest busy;busy.headers["X-Duck-Password"]="synthetic-password-only";execution::busy=true;handleUsbObservations(&busy);check(busy.status==409&&bootCalls==0,"contention exported live capture");}report("UI02",before);
 reset();before=checks;{start();usb_observer::service(1000,true);for(unsigned i=0;i<65;++i){auto e=setup(0x80,6,uint16_t(i));deliver(e);}AsyncWebServerRequest r;read(r);contains(r.body,"\"state\":\"OVERFLOW\"");contains(r.body,"\"count\":64");contains(r.body,"\"windowElapsedMs\":null");contains(r.body,"\"overflow\":true");}report("UI03",before);
 reset();before=checks;{start();auto e=setup();deliver(e);usb_observer::service(1000,true);usb_observer::service(999,true);AsyncWebServerRequest r;read(r);contains(r.body,"\"state\":\"CLOCK_ERROR\"");contains(r.body,"\"windowElapsedMs\":null");}report("UI04",before);
 reset();before=checks;{start();usb_observer::service(1000,true);usb_observer::countersForTest(UINT32_MAX,0,1,0);auto e=setup();deliver(e);AsyncWebServerRequest r;read(r);contains(r.body,"\"state\":\"EXHAUSTED\"");contains(r.body,"\"windowElapsedMs\":null");}report("UI05",before);
 reset();before=checks;{start();auto e=setup();deliver(e);usb_observer::service(UINT32_MAX-4999,true);usb_observer::service(0,true);AsyncWebServerRequest r;read(r);contains(r.body,"\"state\":\"COMPLETE\"");contains(r.body,"\"windowFinishedMs\":0");contains(r.body,"\"windowElapsedMs\":5000");}report("UI06",before);
 reset();before=checks;{start();auto supported=setup();deliver(supported);auto unsupported=setup(0x80,255,0x2222);deliver(unsupported);usb_observer::service(1000,true);usb_observer::service(6000,true);const auto s=usb_observer::snapshot();check(s.unsupported==1&&(s.unsupportedReasons&1),"real unsupported reason not recorded");AsyncWebServerRequest r;read(r);contains(r.body,"\"state\":\"UNSUPPORTED\"");contains(r.body,"\"unsupported\":1,\"unsupportedReasons\":1");contains(r.body,"\"windowElapsedMs\":5000");contains(r.body,"\"classificationReason\":\"NO_VALIDATED_RULE\"");contains(r.body,"\"wValue\":256");std::ofstream(out+"/integration-unsupported.json")<<r.body;}report("UI07",before);
 reset();before=checks;{start();auto e=setup();deliver(e);usb_observer::service(1000,true);usb_observer::service(6000,true);auto resetEvent=event(DCD_EVENT_BUS_RESET);deliver(resetEvent);AsyncWebServerRequest r;read(r);contains(r.body,"\"generation\":2");contains(r.body,"\"count\":0");contains(r.body,"\"windowElapsedMs\":null");contains(r.body,"\"unsupported\":0,\"unsupportedReasons\":0");auto unplug=event(DCD_EVENT_UNPLUGGED);deliver(unplug);AsyncWebServerRequest disconnected;read(disconnected);contains(disconnected.body,"\"state\":\"UNPLUGGED\"");contains(disconnected.body,"\"windowElapsedMs\":null");}report("UI08",before);
 reset();std::cout<<"{\"summary\":true,\"groups\":"<<groups<<",\"assertions\":"<<checks<<",\"status\":\"PASS\"}"<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
